import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { raster } from "./tokens.stylex";
import { rs } from "./rs";
import { hidden } from "./hidden.stylex";

interface RadioGroupContextValue {
  name: string;
  value: string | undefined;
  setValue: (value: string) => void;
}

const RadioGroupContext = React.createContext<RadioGroupContextValue | null>(null);

export interface RadioGroupProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  name?: string;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
}

export function RadioGroup({
  name,
  value,
  defaultValue,
  onValueChange,
  children,
  ...props
}: RadioGroupProps) {
  const autoName = React.useId();
  const [inner, setInner] = React.useState(defaultValue);
  const isControlled = value !== undefined;
  const current = isControlled ? value : inner;
  const setValue = (next: string) => {
    if (!isControlled) setInner(next);
    onValueChange?.(next);
  };
  return (
    <div role="radiogroup" {...props}>
      <RadioGroupContext.Provider value={{ name: name ?? autoName, value: current, setValue }}>
        {children}
      </RadioGroupContext.Provider>
    </div>
  );
}

export interface RadioProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "type" | "value"> {
  value: string;
  label?: React.ReactNode;
}

const styles = stylex.create({
  radio: {
    display: "flex",
    alignItems: "center",
    gap: {
      default: 9,
      ["@media (max-width: 640px)"]: 12,
    },
    fontSize: {
      default: 14,
      ["@media (max-width: 640px)"]: 17,
    },
    color: raster.ink,
    letterSpacing: "-0.01em",
    minHeight: {
      default: null,
      ["@media (max-width: 640px)"]: raster.hit,
    },
  },
  dot: {
    width: {
      default: 16,
      ["@media (max-width: 640px)"]: 22,
    },
    height: {
      default: 16,
      ["@media (max-width: 640px)"]: 22,
    },
    borderRadius: "50%",
    borderWidth: 1.5,
    borderStyle: "solid",
    borderColor: raster.divider,
    position: "relative",
    flexShrink: 0,
    boxSizing: "border-box",
  },
  on: {
    borderColor: raster.ink,
  },
  fill: {
    position: "absolute",
    inset: {
      default: 3,
      ["@media (max-width: 640px)"]: 5,
    },
    borderRadius: "50%",
    backgroundColor: raster.ink,
  },
});

/** A real native radio inside a RadioGroup; the ink dot mirrors its state. */
export const Radio = React.forwardRef<HTMLInputElement, RadioProps>(function Radio(
  { value, label, className, style, onChange, ...props },
  ref,
) {
  const group = React.useContext(RadioGroupContext);
  const on = group ? group.value === value : undefined;
  const row = rs(["rs-radio", className], styles.radio);
  const sr = rs(["rs-sr"], hidden.sr);
  const mark = rs(["rs-radio-dot", on && "rs-radio-on"], styles.dot, on && styles.on);
  const fill = rs([], styles.fill);
  return (
    <label className={row.className} style={{ ...row.style, ...style }}>
      <input
        ref={ref}
        type="radio"
        className={sr.className}
        style={sr.style}
        name={group?.name}
        value={value}
        checked={on}
        onChange={(e) => {
          group?.setValue(value);
          onChange?.(e);
        }}
        {...props}
      />
      <span className={mark.className} style={mark.style} aria-hidden="true">
        {on ? <span className={fill.className} style={fill.style} /> : null}
      </span>
      {label}
    </label>
  );
});

import * as stylex from "@stylexjs/stylex";

/**
 * StyleX vars alias Raster CSS custom properties. Not a second scale.
 * Values live in packages/core/css/tokens.css (generated from src/tokens.ts).
 */
export const raster = stylex.defineVars({
  paper: "var(--bg)",
  ink: "var(--text)",
  gray: "var(--text-secondary)",
  accent: "var(--accent)",
  divider: "var(--divider)",
  dividerSubtle: "var(--divider-subtle)",
  tableAlt: "var(--table-alt)",
  gridLine: "var(--grid-line)",
  radiusSm: "var(--radius-sm)",
  radius: "var(--radius)",
  radiusChrome: "var(--radius-chrome)",
  radiusIn: "var(--radius-in)",
  pad: "var(--pad)",
  gutter: "var(--gutter)",
  module: "var(--grid-size)",
  gridImage: "var(--grid-image)",
  gridPos: "var(--grid-pos)",
  hit: "var(--hit)",
  controlH: "var(--control-h)",
  controlFs: "var(--control-fs)",
  controlLabel: "var(--control-label)",
  durationSnap: "var(--duration-snap)",
  duration: "var(--duration)",
  durationConfirm: "var(--duration-confirm)",
  ease: "var(--ease)",
  transition: "var(--transition)",
  textScale: "var(--text-scale)",
  hairline: "1px",
});

/** Inter stack. Same as body in base.css. Not a token var — @font-face stays CSS. */
export const rasterFont =
  "Inter, -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif";

export const rasterMono = "ui-monospace, SFMono-Regular, Menlo, monospace";

/** Compile-time media keys. StyleX only folds defineConsts, not plain strings. */
export const mq = stylex.defineConsts({
  phone: "@media (max-width: 640px)",
  mobileGrid: "@media (max-width: 480px)",
  at900: "@media (min-width: 900px)",
  at899: "@media (max-width: 899px)",
  rail: "@media (min-width: 1024px)",
  wide: "@media (min-width: 1440px)",
  reduce: "@media (prefers-reduced-motion: reduce)",
  touch: "@media (hover: none)",
});

/** Phone recut (≤640). Desktop stays the poster. */
export const phone = mq.phone;

/** Mobile grid (≤480). */
export const mobileGrid = mq.mobileGrid;

/** Catalog rail. */
export const rail = mq.rail;

/** Wide catalog. */
export const wide = mq.wide;

import type { CSSProperties } from "react";
import * as stylex from "@stylexjs/stylex";
import { cx } from "./cx";

type StyleXProps = { className?: string; style?: CSSProperties };

/** Merge Raster class names with StyleX props. CSS-first classes stay on the node. */
export function rs(classNames: Array<string | false | null | undefined>, ...styles: unknown[]): StyleXProps {
  const sx = (stylex.props as (...args: unknown[]) => StyleXProps)(...styles);
  return {
    className: cx(...classNames, sx.className),
    style: sx.style,
  };
}

import * as stylex from "@stylexjs/stylex";
import { raster } from "./tokens.stylex";

/** Screen-reader only. Matches .rs-sr */
export const hidden = stylex.create({
  sr: {
    position: "absolute",
    width: 1,
    height: 1,
    padding: 0,
    margin: -1,
    overflow: "hidden",
    clip: "rect(0, 0, 0, 0)",
    whiteSpace: "nowrap",
    borderWidth: 0,
  },
  srFocusMark: {
    outlineWidth: {
      default: null,
      ":focus-visible + *": 1.5,
    },
    outlineStyle: {
      default: null,
      ":focus-visible + *": "solid",
    },
    outlineColor: {
      default: null,
      ":focus-visible + *": raster.ink,
    },
    outlineOffset: {
      default: null,
      ":focus-visible + *": 2,
    },
  },
});

/** Join class names, dropping falsy parts. */
export function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}
